mapper.select:
SELECT * FROM review WHERE product_id = #{productId}
ORDER BY created_at DESC
LIMIT #{offset}, #{size}

SELECT r.* FROM review r
JOIN product p ON r.product_id = p.id
WHERE p.merchant_id = #{merchantId}
ORDER BY r.created_at DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE review
content = #{content}, rating = #{rating}, images = #{images}, is_anonymous = #{isAnonymous}, merchant_reply = #{merchantReply}, merchant_reply_time = #{merchantReplyTime}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
